      SUBROUTINE MR3R2CC     MULTIPLIES RC3 AND RC2 AND STORES RESULT IN RC2CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC3.CIN'      INCLUDE 'US.CIN'CC--------------------------------------------------------------------      IF (R2P) GO TO 50      DO 10 JK = 1, 36   10 RC2L(JK) = RC3L(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TC2L(JKM) = TC3L(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   UC2L(JKLM) = UC3L(JKLM)      ENDIF      GO TO 100C   50 IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RC3,RC2)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CAB2(RS,TS,RC3,TC3,RC2,TC2)      ELSE IF (NORD2 .EQ. 3) THEN        CALL CAB3(RS,TS,US,RC3,TC3,UC3,RC2,TC2,UC2)      ENDIFC      DO 60 JK = 1, 36   60 RC2L(JK) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 70 JKM = 1, 105   70   TC2L(JKM) = TSL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 80 JKLM = 1, 280   80   UC2L(JKLM) = USL(JKLM)      ENDIFC  100 RETURN      END